// Stock AF target selection screen, no overlay.
// Records the screen after native keys, full-cell readbacks, getter and setter
// callers, and call targets during an editor tour.
// apply_uiin_layout only maps the lab's key names onto E147's stock UI_IN table.
// No 0x120b harness. No firmware write. Do not edit this file after it has run.
// Usage: node26 work/scripts/stock_probe_m1.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/stock_probe_m1.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const BASE = 0x60021020;
const WATCH = new Set([
  0x99a1, 0x9a41, 0x5962, 0x1dd1, 0x1de1, 0x1df1, 0x1e01,
  0xdfa1, 0x99d2, 0x9fa1, 0x84d1, 0x88b2, 0x90d1, 0xe91, 0x1db1, 0x1dc1, 0x5a11, 0x90a1,
]);
const GETTER = 0x60063380;
const SETTER = 0x60063431;
const OUT = resolve('work/out/stock-probe-m1.jsonl');
const DEADLINE = Date.now() + 18 * 60 * 1000;

function shaFile(p) {
  const data = readFileSync(p);
  return { path: p.replaceAll('\\', '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}

const { loadNand, loadImage, loadBlock, createHash: fwHash, ORIGINAL, BLOCK, NAND } = await use('checks/lib/env.mjs');
const { IMAGE_BASE, A } = await use('src/fw/model.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');
const { fileNvram } = await use('host/nvram.mjs');
const { setExecTrace } = await use('src/core/cpu.mjs');
const { setForceHelper } = await use('src/core/interp.mjs');

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
const seeds = [
  resolve(checkout, 'emu/checks/lib/env.mjs'),
  resolve(checkout, 'emu/src/fw/model.mjs'),
  resolve(checkout, 'emu/src/lab/player.mjs'),
  resolve(checkout, 'emu/src/lab/play.mjs'),
  resolve(checkout, 'emu/scenarios/session_replay.mjs'),
  resolve(checkout, 'emu/src/lab/menuwalk.mjs'),
  resolve(checkout, 'emu/checks/lib/png.mjs'),
  resolve(checkout, 'emu/src/lab/display.mjs'),
  resolve(checkout, 'emu/host/nvram.mjs'),
  resolve(checkout, 'emu/src/core/cpu.mjs'),
  resolve(checkout, 'emu/src/core/interp.mjs'),
  fileURLToPath(import.meta.url),
];
const seen = new Map();
const queue = [...seeds];
while (queue.length) {
  const file = queue.pop();
  if (!file || seen.has(file) || !existsSync(file)) continue;
  const data = readFileSync(file);
  seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
  const text = data.toString('utf8');
  IMPORT_RE.lastIndex = 0;
  let match;
  while ((match = IMPORT_RE.exec(text))) {
    const next = resolveSpec(file, match[1]);
    if (next && !seen.has(next)) queue.push(next);
  }
}
const resources = [ORIGINAL, BLOCK, NAND,
  resolve('inputs/00_0100_50000020.decoded.bin'),
  resolve('inputs/02_0106_458c0020.decoded.bin'),
].filter((p) => p && existsSync(p)).map(shaFile);
mkdirSync(resolve('work/out'), { recursive: true });
writeFileSync(resolve('work/out/import-inventory-m1.json'), JSON.stringify({
  note: 'SHA-256 taken before the stock session starts.',
  hashed: 'execution',
  modules: [...seen.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([file, rec]) => ({
    path: file.replaceAll('\\', '/'), sha256: rec.sha256, bytes: rec.bytes,
  })),
  resources,
}, null, 2) + '\n');

const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  const brief = {
    step: row.step, screen: row.screen, state: row.stateName, texts: row.texts,
    highlight: row.highlight, diff: row.diff, gets: row.getCount, sets: row.setCount,
    calls: row.callCount, error: row.error || null,
  };
  console.log(JSON.stringify(brief));
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const hex = (v) => '0x' + (v >>> 0).toString(16);
const native = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;

const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const nv = fileNvram(resolve('work/out/nvram-stock-m1.json'));
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, nvram: nv, patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

let failed = null;
try {
  pl.open_session();
  const s = pl.session;
  const l = s.lab;
  const gate = { reading: false, on: false };
  const gets = [];
  const sets = [];
  const otherGet = new Map();
  const otherSet = new Map();
  let getDropped = 0;
  let setDropped = 0;
  let tracing = false;
  let lastPc = 0;
  let lastOp = 0;
  const callEntries = [];
  const seenCalls = new Set();
  const noteOther = (map, key, index) => {
    if (map.size > 80 && !map.has(key + ':' + index)) return;
    const id = key.toString(16) + ':' + index;
    map.set(id, (map.get(id) || 0) + 1);
  };
  const onGet = (r) => {
    if (!gate.on || gate.reading) return;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    if (!WATCH.has(key)) { noteOther(otherGet, key, index); return; }
    if (gets.length >= 1500) { getDropped += 1; return; }
    gets.push({ key: hex(key), index, caller: hex(r.mdr >>> 0) });
  };
  const onSet = (r) => {
    if (!gate.on || gate.reading) return;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    if (!WATCH.has(key)) { noteOther(otherSet, key, index); return; }
    if (sets.length >= 800) { setDropped += 1; return; }
    sets.push({ key: hex(key), index, d2: r.d2 >>> 0, a0: hex(r.a0 >>> 0), caller: hex(r.mdr >>> 0) });
  };
  l.observe(native(GETTER), (_lab, r) => onGet(r), 'obs-60063380');
  l.observe(native(SETTER), (_lab, r) => onSet(r), 'obs-60063431');
  setExecTrace((pc, op) => {
    if (!tracing) return;
    const p = pc >>> 0;
    const delta = (p - lastPc) >>> 0;
    if (lastPc && (delta > 6 || p < lastPc) && callEntries.length < 500) {
      let call = lastOp === 0xdd || lastOp === 0xcd;
      if (!call && (lastOp === 0xfc || lastOp === 0xfa)) {
        try { call = l.sim.read(lastPc, 2)[1] === 0xff; } catch { /* unreadable */ }
      }
      if (call && !seenCalls.has(p)) {
        seenCalls.add(p);
        callEntries.push(hex(p));
      }
    }
    lastPc = p;
    lastOp = op & 0xff;
  });
  const readByte = (addr) => l.sim.read(addr, 1)[0];
  const callSaved = (fn) => {
    const saved = l.sim.registers();
    const was = tracing;
    tracing = false;
    gate.reading = true;
    try { return fn(); }
    finally { gate.reading = false; tracing = was; l.sim.reset(saved); }
  };
  const readKey = (key, index) => callSaved(() => l.call(native(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff);
  const arr = (key, n) => Array.from({ length: n }, (_, i) => readKey(key, i));
  const cells = () => ({
    profileByte: readByte(0xa031e920),
    k99a1: arr(0x99a1, 8),
    k9a41: arr(0x9a41, 2),
    k5962: arr(0x5962, 6),
    k1dd1: arr(0x1dd1, 10),
    k1de1: arr(0x1de1, 8),
    k1df1: arr(0x1df1, 8),
    k1e01: readKey(0x1e01, 0),
    kdfa1: readKey(0xdfa1, 0),
    k99d2: arr(0x99d2, 3),
    k9fa1: arr(0x9fa1, 3),
    k84d1: readKey(0x84d1, 0),
    k88b2: readKey(0x88b2, 0),
    k90d1: arr(0x90d1, 8),
    ke91: readKey(0xe91, 3),
    k1db1: readKey(0x1db1, 0),
    k1dc1: readKey(0x1dc1, 0),
    k5a11: arr(0x5a11, 11),
    k90a1: [readKey(0x90a1, 0), readKey(0x90a1, 1)],
  });
  const idle = (ms) => { const to = l.lab_time() + ms * 1e6; while (l.lab_time() < to) s.idle_slice(Math.min(to, l.lab_time() + 50e6)); };
  const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
  const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(450); };
  const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 40 });
  const screenOf = () => {
    try {
      const st = l.state();
      return { screen: s.screen(), state: st, stateName: l.state_names.get(st) ?? null };
    } catch (e) {
      return { screen: null, state: null, stateName: null, error: String(e && e.message || e) };
    }
  };
  const textsOf = () => {
    try {
      const scr = walk.read();
      const texts = scr.texts.map((t) => t.text);
      let highlight = null;
      for (const t of scr.texts) {
        try {
          const listed = walk.list(scr, t);
          if (listed && listed.cursor != null && listed.rows[listed.cursor]) { highlight = listed.rows[listed.cursor].text; break; }
        } catch { /* not a list */ }
      }
      return { texts, highlight, frame: scr.frame, error: null };
    } catch (e) {
      let frame = null;
      try { frame = s.frame('boundary'); } catch { /* no frame */ }
      return { texts: [], highlight: null, frame, error: String(e && e.message || e) };
    }
  };
  let shotN = 0;
  const snap = (step, extra = {}) => {
    const view = textsOf();
    const st = screenOf();
    let file = null;
    if (!view.frame) throw new Error('screenshot failed at ' + step + ': ' + (view.error || 'no frame'));
    file = resolve('work/out/stock-m1-' + String(shotN).padStart(3, '0') + '-' + step.replace(/[^a-z0-9-]+/gi, '_') + '.png');
    shotN += 1;
    write_png(file, view.frame[0], view.frame[1], words_to_rgb(view.frame[2]));
    const now = cells();
    const diff = extra.before ? diffCells(extra.before, now) : [];
    const top = (map) => [...map.entries()].sort((a, b) => b[1] - a[1]).slice(0, 12).map(([id, n]) => ({ id, n }));
    const row = {
      hook: 'observe', role: 'observe', step, ...st,
      texts: view.texts, highlight: view.highlight, textError: view.error,
      screenshot: file.split(/[/\\]/).pop(),
      cells: now, diff,
      gets, sets, getDropped, setDropped, otherGet: top(otherGet), otherSet: top(otherSet),
      getCount: gets.length, setCount: sets.length,
      calls: callEntries.slice(), callCount: callEntries.length,
      ...extra.rest,
    };
    emit(row);
    return row;
  };
  const clearLogs = () => {
    gets.length = 0; sets.length = 0; getDropped = 0; setDropped = 0;
    otherGet.clear(); otherSet.clear();
    callEntries.length = 0; seenCalls.clear(); lastPc = 0;
  };
  const timeLeft = () => Date.now() < DEADLINE;
  const safe = (fn) => { try { return fn() || null; } catch (e) { return String(e && e.message || e); } };

  emit({
    hook: 'observe', role: 'observe', step: 'setup',
    note: 'Stock image. apply_uiin_layout maps lab key names onto the E147 UI_IN table. No overlay. No 0x120b harness. Getter 0x60063380 and setter 0x60063431 are observed, not replaced.',
    imageBase: hex(IMAGE_BASE), A_getter: hex(A(GETTER)), nativeGetter: hex(native(GETTER)),
    resources: resources.map((r) => ({ path: r.path, sha256: r.sha256 })),
  });
  gate.on = true;
  idle(1200);
  let before = snap('baseline').cells;

  const openers = ['ok', 'up', 'right', 'left', 'down', 'info', 'js_press', 'js_up', 'delete', 'afmeter', 'lvkey'];
  const escapeShooting = () => {
    for (let i = 0; i < 6; i++) {
      if (s.screen() === 'shooting') return true;
      if (!timeLeft()) return false;
      clearLogs();
      const err = safe(() => press('menu'));
      snap('escape-' + i, { before, rest: { pressError: err } });
      before = cells();
    }
    return s.screen() === 'shooting';
  };
  const tour = (tag) => {
    const actions = [
      ['right', () => press('right')],
      ['up', () => press('up')],
      ['left', () => press('left')],
      ['down', () => press('down')],
      ['info', () => press('info')],
      ['js_press', () => press('js_press')],
      ['dial-main', () => { s.dial_input('main', 1); s.camapp.pump(); idle(450); }],
      ['dial-sub', () => { s.dial_input('sub', 1); s.camapp.pump(); idle(450); }],
      ['iso', () => press('iso')],
      ['ok', () => press('ok')],
    ];
    tracing = true;
    setForceHelper(true);
    try {
      for (const [name, fn] of actions) {
        if (!timeLeft()) break;
        if (s.screen() === 'shooting') break;
        clearLogs();
        const err = safe(fn);
        const row = snap(tag + '-' + name, { before, rest: { pressError: err } });
        before = row.cells;
      }
    } finally {
      tracing = false;
      setForceHelper(false);
    }
  };

  for (const k of openers) {
    if (!timeLeft()) break;
    if (s.screen() !== 'shooting') {
      if (!escapeShooting()) break;
      before = cells();
    }
    clearLogs();
    const err = safe(() => press(k));
    const row = snap('open-' + k, { before, rest: { pressError: err } });
    before = row.cells;
    if (row.screen === 'direct' || (row.screen && row.screen !== 'shooting' && row.screen !== 'menu' && row.diff.length)) {
      tour('open-' + k);
      clearLogs();
      safe(() => press('menu'));
      const back = snap('open-' + k + '-menu', { before });
      before = back.cells;
      escapeShooting();
      before = cells();
    }
  }

  if (timeLeft() && s.screen() === 'shooting') {
    clearLogs();
    safe(() => press('menu'));
    let page = snap('menu', { before });
    before = page.cells;
    for (let i = 0; i < 24 && timeLeft(); i++) {
      if ((page.texts || []).some((t) => t.includes('AF Target Settings'))) break;
      clearLogs();
      safe(() => press('left'));
      page = snap('left-' + i, { before });
      before = page.cells;
    }
    for (let row = 0; row < 6 && timeLeft(); row++) {
      if (s.screen() !== 'menu') break;
      clearLogs();
      const err = safe(() => press('ok'));
      const opened = snap('row-' + row + '-ok', { before, rest: { pressError: err, highlightBefore: page.highlight } });
      before = opened.cells;
      const leftPage = !(opened.texts || []).some((t) => String(t).includes('AF Target Settings'));
      if (opened.screen === 'direct' || opened.screen === 'other' || (opened.screen === 'menu' && leftPage)) {
        tour('row-' + row);
        clearLogs();
        safe(() => press('menu'));
        const back = snap('row-' + row + '-cancel', { before });
        before = back.cells;
      } else if (opened.screen === 'menu' && opened.texts.join('|') !== page.texts.join('|')) {
        clearLogs();
        safe(() => press('right'));
        snap('row-' + row + '-right', { before });
        before = cells();
        clearLogs();
        safe(() => press('menu'));
        snap('row-' + row + '-cancel', { before });
        before = cells();
      }
      if (!timeLeft()) break;
      if (s.screen() !== 'menu' || !(textsOf().texts || []).some((t) => String(t).includes('AF Target Settings'))) {
        escapeShooting();
        break;
      }
      clearLogs();
      safe(() => press('down'));
      page = snap('row-' + row + '-down', { before });
      before = page.cells;
    }
  }

  if (timeLeft()) {
    const pose0 = cells();
    const err = safe(() => { s.switch_input('rotate', 1); s.camapp.pump(); idle(400); });
    clearLogs();
    snap('rotate-1', { before: pose0, rest: { pressError: err } });
    const err2 = safe(() => { s.switch_input('monitor', 0); s.camapp.pump(); idle(400); });
    clearLogs();
    snap('monitor-0', { before: pose0, rest: { pressError: err2 } });
  }
  emit({ hook: 'observe', role: 'observe', step: 'done', ok: true, deadlineHit: !timeLeft() });
} catch (e) {
  failed = String(e && e.stack ? e.stack : e);
  emit({ hook: 'observe', role: 'observe', step: 'done', ok: false, error: failed });
  process.exitCode = 1;
} finally {
  try { setExecTrace(null); setForceHelper(false); } catch { /* trace already clear */ }
  if (pl.session) pl.close_session();
  writeFileSync(OUT, lines.join('\n') + (lines.length ? '\n' : ''));
}
if (failed) process.exit(1);

function diffCells(a, b, path = '', out = []) {
  if (Array.isArray(a) && Array.isArray(b)) {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) out.push([path + '[' + i + ']', a[i], b[i]]);
    return out;
  }
  if (a && b && typeof a === 'object' && typeof b === 'object') {
    for (const k of Object.keys(a)) diffCells(a[k], b[k], path ? path + '.' + k : k, out);
    return out;
  }
  if (a !== b) out.push([path, a, b]);
  return out;
}
